// Builds supabase/test-project-setup.sql: every migration in order, in one file, for a NEW
// Supabase project used only for testing. Never run the result on the live Osaka database.
// Usage: node scripts/build-test-setup.mjs
import { readdir, readFile, writeFile } from "node:fs/promises";

const dir = new URL("../supabase/migrations/", import.meta.url);
const files = (await readdir(dir)).filter(name => name.endsWith(".sql")).sort();
const parts = [
  "-- HEAT test project setup. Generated by scripts/build-test-setup.mjs; do not edit by hand.",
  "-- For a NEW, EMPTY Supabase project only. Do NOT run this on the live Osaka Miami project.",
  `-- Contains ${files.length} migrations, ${files[0]} to ${files.at(-1)}.`,
  "",
];
for (const file of files) {
  parts.push(`-- ===== ${file} =====`, await readFile(new URL(file, dir), "utf8"), "");
  // Production has menu_items.details (added by hand before migrations were kept here).
  if (file === "001_heat.sql") parts.push("-- ===== menu_items.details (exists in production, no migration file) =====",
    "alter table public.menu_items add column if not exists details jsonb;", "");
}
await writeFile(new URL("../supabase/test-project-setup.sql", import.meta.url), parts.join("\n"));
console.log(`Wrote supabase/test-project-setup.sql with ${files.length} migrations.`);
